// Explicit live acceptance: a public Smith excerpt, generated by this agent, private import only.
import {readFile,writeFile,mkdtemp} from 'node:fs/promises';import {join} from 'node:path';
import {prepareLocal,nextLocal,respondLocal} from '../../core/src/local-processing.js';
import {publishLocal} from '../../core/src/local-publish.js';import {credentials,serviceCall} from '../../core/src/account.js';
const session=await credentials(true),dir=await mkdtemp('/private/tmp/awb-byoa-smith-'),work=join(dir,'work');
const replies=JSON.parse(await readFile(new URL('./fixtures/book-agent-import/smith-tax-responses.json',import.meta.url)));
await prepareLocal(new URL('./fixtures/book-astra-eval/tax.txt',import.meta.url).pathname,{output:work,destination:'library',title:replies.section.title,author:'Adam Smith'});
const stages=[];let step;
for(let i=0;i<12;i++){
 step=await nextLocal(work);if(step.status==='ready')break;if(step.status!=='needs_agent_response')throw Error('Unexpected local state: '+step.status);
 const r=step.request;stages.push(r.stage);let value;
 if(r.stage==='book_section')value=replies.section;
 else if(r.stage==='book_synthesis')value=replies.book;
 else if(r.stage==='book_cited_review'){const claims=JSON.parse(r.input).claims;value={supported:true,issues:[],checks:claims.map(c=>({id:c.id,supported:true,reason:'The cited passage states this maxim; the response preserves its scope and does not add rates or guarantees.'}))};}
 else if(r.stage==='book_synthesis_review')value={supported:true,issues:[]};else throw Error('Unexpected stage '+r.stage);
 const path=join(dir,'response.json');await writeFile(path,JSON.stringify(value));await respondLocal(work,{input:path,request:r.id});
}
await writeFile('/private/tmp/awb-byoa-live-work.json',JSON.stringify({dir:work,stages,result:step},null,2));
if(step?.library?.status!=='imported')throw Error('Local work is ready but import is not complete: '+JSON.stringify(step?.library));
const repeated=await publishLocal(work);if(repeated.id!==step.library.id)throw Error('Repeated import created a duplicate');
const query='How should I evaluate certainty and convenience in taxation?';
const found=await serviceCall('book-library',{action:'search',question:query,book:repeated.id},session.token);
await writeFile('/private/tmp/awb-byoa-live-result.json',JSON.stringify({work,stages,import:repeated,repeatSameId:true,retrieval:found},null,2));
console.log(JSON.stringify({id:repeated.id,work,repeatSameId:true,retrievalStatus:found.status,keys:Object.keys(found)}));
